SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, ROUND(monthly_fee / SUM(monthly_fee) OVER (PARTITION BY customer_id), 4) AS monthly_fee_share, AVG(monthly_fee) OVER (PARTITION BY plan, status ORDER BY end_date, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS monthly_fee_avg_6_prior, ROW_NUMBER() OVER (PARTITION BY customer_id, status ORDER BY end_date DESC, id) AS row_seq FROM subscriptions;
